      "content": "{\n  \"name\": \"dsh-language-guard\",\n  \"version\": \"0.3.4\",\n  \"description\": \"Lock model reasoning, replies and tool-call descriptions to a target language in DeepSeek Harness (Simplified Chinese by default): three strength levels, configurable prompt sections, periodic reminders, a settings panel with a quick language switch and a live \\\"what is active\\\" status line.\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./icon\": \"./icon.svg\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"icon\": \"icon.svg\",\n  \"files\": [\n    \"lib\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"locale/*.json\",\n    \"icon.svg\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.1-rc.2\"\n  },\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.5\",\n    \"@deepseek-ai/dsh-llm\": \">=0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \">=3.18.2\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.5\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"scripts\": {\n    \"test\": \"node scripts/verify-language.mjs && node scripts/verify-mirror.mjs && node scripts/verify-client.mjs && node scripts/verify-dispose.mjs && node scripts/verify-manifest.mjs && bash scripts/verify-checklist.sh\",\n    \"prepublishOnly\": \"node scripts/verify-release.mjs\",\n    \"verify:release\": \"node scripts/verify-release.mjs --verify\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"chinese\",\n    \"language\",\n    \"locale\",\n    \"system-prompt\",\n    \"i18n\"\n  ],\n  \"author\": {\n    \"name\": \"sunjingzhi\",\n    \"email\": \"dlyh@vip.qq.com\",\n    \"url\": \"https://github.com/58fly\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/58fly/dsh-language-guard.git\"\n  },\n  \"homepage\": \"https://github.com/58fly/dsh-language-guard#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/58fly/dsh-language-guard/issues\"\n  }\n}\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-language-guard —— Host 半。\n *\n * 职责：\n * 1. 注册三个常驻 system prompt section（head / mid / tail），切档只切 `text()` 的返回值；\n * 2. D 档注册 `agent/pre-step` 监听，每 N 轮追加一条语言自检提醒；\n * 3. 提供 `/language` 斜杠命令与设置表单（settings 服务懒注入）；\n * 4. 自动语言模式（0.2.0）：读界面语言，按 `languageMode` 决定是否跟随。\n *\n * 合规边界（docs/decisions/01-mechanism.md 第 1 节）：\n * - 不监听系统提示词装配事件去增删文本（只用 section 注册，验收 C4 会 grep 该事件名，必须为空）；\n * - 不改写流式响应中的推理增量（那会破坏日志与签名回放）；\n * - 不 append 新 type 的 session 事件（提醒走既有 user/message）；\n * - section 文本在一次会话内稳定，不依赖轮次、时间或随机数。\n *\n * 唯一的真源是 docs/decisions/01-mechanism.md；文案在 lib/text.js 里逐字照抄。\n */\n\n/**\n * schemastery 是 peer 依赖，由宿主的解析链提供。**惰性解析**（0.3.0）：\n * 静态 import 失败时 cordis Loader 把整行当成「非致命跳过」——插件根本不挂载，\n * 而所有宿主日志都是绿的，用户装完没有任何反应也查不出原因。\n * 降级成 `undefined` 后 Loader 把原始 config 原样传下来，提示词注入、语言解析\n * 与 `/language` 命令照常工作，只有设置表单的 schema 投影缺失，并在日志留一行告警。\n */\nlet z = null;\ntry {\n  z = (await import('@deepseek-ai/schemastery')).default;\n} catch (error) {\n  z = null;\n  console.warn(\n    '[dsh-language-guard] @deepseek-ai/schemastery 不可解析：设置表单的 schema 投影缺失，'\n      + '提示词注入与语言解析不受影响。原因：'\n      + (error && error.message ? error.message : String(error)),\n  );\n}\n\nimport { headText, midText, tailText } from './text.js';\nimport {\n  DEFAULT_LANGUAGE,\n  DEFAULT_STRENGTH,\n  normalizeBoolean,\n  normalizeInterval,\n  normalizeStrength,\n  normalizeText,\n  resolveLanguage,\n} from './state.js';\nimport { MODE_MANUAL, effectiveMode, mapPreference, resolveSource } from './language.js';\nimport { registerCycle } from './cycle.js';\nimport { registerCommands } from './commands.js';\n\n/**\n * 只声明 `systemPrompt`：它是本插件的核心依赖，缺了就没有任何意义。\n * `settings` / `commands` 用 `ctx.inject([...])` 懒注入 —— 缺这两个服务的部署\n * （headless、无交互 UI）仍然应该把语言约束注入 system prompt，而不是永久 pending。\n */\nexport const inject = ['systemPrompt'];\n\n/**\n * section 名与 order 固定，永不注销；切档只切 text 返回值（01-mechanism.md 2.2）。\n * order 直接写字面量：注册接口要求有限数字，且 mid 必须用 5100（tools:sdk 恰好是 5000，\n * 同序时 `language-guard:mid` 会按 name 字典序排到工具说明之前）。\n */\nconst HEAD_SECTION = 'language-guard:head';\nconst MID_SECTION = 'language-guard:mid';\nconst TAIL_SECTION = 'language-guard:tail';\n\n/**\n * 读取一个配置字段的当前值。\n * volatile 引用只有 `get()`（写入由宿主 Loader 负责），因此这里只读不写。\n * @param {any} config 插件配置对象\n * @param {string} field 字段名\n * @returns {unknown}\n */\nfunction readField(config, field) {\n  const ref = config?.[field];\n  if (ref !== undefined && ref !== null && typeof ref.get === 'function') return ref.get();\n  return ref;\n}\n\nexport function apply(ctx, config) {\n  let warnedStrength = false;\n  let warnedInterval = false;\n\n  /** 输出一次告警，避免每步刷屏 */\n  const warnOnce = (kind, message) => {\n    if (kind === 'strength' ? warnedStrength : warnedInterval) return;\n    if (kind === 'strength') warnedStrength = true;\n    else warnedInterval = true;\n    try {\n      const logger = typeof ctx.logger === 'function' ? ctx.logger('language-guard') : ctx.logger;\n      logger?.warn?.(message);\n    } catch {\n      // 日志不可用不应影响提示词注入\n    }\n  };\n\n  /** 当前档位（规范化 + 兜底） */\n  const strength = () => {\n    const result = normalizeStrength(readField(config, 'strength'));\n    if (!result.valid) {\n      warnOnce('strength', `未知的强度档位，已回退到 \"${DEFAULT_STRENGTH}\"（可选值：B / C / D）`);\n    }\n    return result.value;\n  };\n\n  /** 当前注入间隔（规范化 + 兜底） */\n  const interval = () => {\n    const result = normalizeInterval(readField(config, 'injectEveryNRounds'));\n    if (!result.valid) {\n      warnOnce('interval', `注入间隔超出 3–50 的范围，已按 ${result.value} 处理`);\n    }\n    return result.value;\n  };\n\n  /** 当前目标语言（`/language` 内存覆盖 > 自动解析 / 配置值 > 默认值） */\n  const language = () => {\n    const raw = readField(config, 'targetLanguage');\n    return resolveLanguage(typeof raw === 'string' ? raw : DEFAULT_LANGUAGE, {\n      mode: readField(config, 'languageMode'),\n      preference: cachedPreference,\n    });\n  };\n\n  /** 配置里的目标语言（不受 `/language` 覆盖影响，也不受自动解析影响） */\n  const configuredLanguage = () => {\n    const raw = readField(config, 'targetLanguage');\n    const text = typeof raw === 'string' ? raw.trim() : '';\n    return text || DEFAULT_LANGUAGE;\n  };\n\n  /**\n   * 有效语言模式（三态 → 两态）。\n   *\n   * `languageMode` 的 schema 默认值是空串（「未选择」），不是 `'auto'`：\n   * 只有这样才能区分「用户显式选了自动」与「用户从没设置过」。0.1.x 用户\n   * 手选过 `targetLanguage: ja` 时，空串 + 非默认值会被判成 manual，\n   * 升级后继续用 `ja`，不会被界面语言静默覆盖（票 #14 迁移规则）。\n   */\n  const currentMode = () =>\n    effectiveMode({\n      languageMode: readField(config, 'languageMode'),\n      targetLanguage: readField(config, 'targetLanguage'),\n      defaultLanguage: DEFAULT_LANGUAGE,\n    });\n\n  /**\n   * 界面语言缓存（`settings.describe()` 的结果）。\n   *\n   * **绝不进 `text()`**：实测单次 describe 约 0.79 ms 读盘 + 1.17 ms schema 投影，\n   * 每次装配都调会把 system prompt 的求值成本抬高一个数量级\n   * （04-auto-language.md 2.4 节）。这里只在 apply 与 `settings/document-updated`\n   * 时刷新，`text()` 只读缓存变量。\n   */\n  let cachedPreference = null;\n\n  /**\n   * 读一次界面语言；任何异常都吞掉返回 null —— 不能因为读不到就让插件抛错。\n   * `settings` 显式传入（懒注入的 child 才有这个服务），不读 `ctx.settings`。\n   */\n  const readLocalePreference = (settings) => {\n    try {\n      if (!settings || typeof settings.describe !== 'function') return null;\n      const rows = settings.describe();\n      const row = Array.isArray(rows) ? rows.find((item) => item?.ns === 'locale') : null;\n      const preference = row?.value?.preference;\n      return typeof preference === 'string' && preference.trim() ? preference : null;\n    } catch {\n      return null;\n    }\n  };\n\n  /**\n   * 刷新界面语言缓存。\n   *\n   * manual 态**直接返回、连 describe 都不调**：用户已经明确指定语言，\n   * 再遍历全部 entry 做 schema 投影纯属浪费（04-auto-language.md 6.3 要点 4）。\n   * 从 manual 切回 auto 时由 `settings/document-updated`（ns = language-guard）触发。\n   */\n  const refreshPreference = (settings) => {\n    if (currentMode() === MODE_MANUAL) {\n      cachedPreference = null;\n      return;\n    }\n    cachedPreference = readLocalePreference(settings);\n  };\n\n  const preserveCodeTerms = () => normalizeBoolean(readField(config, 'preserveCodeTerms'));\n  const extraRules = () => normalizeText(readField(config, 'extraRules'));\n  const overrideHead = () => normalizeText(readField(config, 'overrideHead'));\n\n  // —— 三个常驻 section：一次性注册、永不 dispose，切档只切 text 返回值 ——\n  // 空字符串会被 renderPrompt 的 `.filter(text => text.length > 0)` 过滤，\n  // 因此 B 档的 mid 返回 \"\" 等价于「该段不存在」，不会留下空行。\n  ctx.effect(\n    () =>\n      ctx.systemPrompt.section({\n        name: HEAD_SECTION,\n        order: -2000,\n        interpolate: false,\n        text: () =>\n          headText({\n            language: language(),\n            preserveCodeTerms: preserveCodeTerms(),\n            overrideHead: overrideHead(),\n            extraRules: extraRules(),\n          }),\n      }),\n    'language-guard: head section',\n  );\n\n  ctx.effect(\n    () =>\n      ctx.systemPrompt.section({\n        name: MID_SECTION,\n        order: 5100,\n        interpolate: false,\n        text: () => (strength() === 'B' ? '' : midText({ language: language() })),\n      }),\n    'language-guard: mid section',\n  );\n\n  ctx.effect(\n    () =>\n      ctx.systemPrompt.section({\n        name: TAIL_SECTION,\n        order: 11200,\n        interpolate: false,\n        text: () => tailText({ language: language(), preserveCodeTerms: preserveCodeTerms() }),\n      }),\n    'language-guard: tail section',\n  );\n\n  // —— D 档周期提醒：注册在插件根 ctx，payload 自带 agent ——\n  ctx.effect(\n    () => registerCycle(ctx, { strength, interval, language }),\n    'language-guard: periodic reminder',\n  );\n\n  // —— `/language` 斜杠命令：输入框里的快捷方式，不写配置 ——\n  registerCommands(ctx, {\n    language,\n    configured: configuredLanguage,\n    mode: currentMode,\n    source: () =>\n      resolveSource({\n        mode: readField(config, 'languageMode'),\n        preference: cachedPreference,\n        fallback: readField(config, 'targetLanguage'),\n        defaultLanguage: DEFAULT_LANGUAGE,\n      }),\n  });\n\n  // —— settings 服务：配置表单 + 界面语言缓存 ——\n  //\n  // 懒注入：headless 部署没有 settings 服务时，auto 态退化为 targetLanguage\n  // 兜底（cachedPreference 保持 null），不能抛错、不能让插件永久 pending。\n  ctx.inject(['settings'], (child) => {\n    // 设置表单：auto:false 表示不在设置页自动生成页面，只提供 volatile 配置表单\n    child.effect(\n      () => child.settings.configure({ auto: false }, ctx.fiber),\n      'language-guard: settings form',\n    );\n\n    // 首次读界面语言（manual 态内部直接返回，不会调 describe）\n    refreshPreference(child.settings);\n\n    // 事件驱动刷新：locale 的 preference 变了、或本插件的 languageMode 变了都重读。\n    //\n    // 为什么不用轮询：describe 单次约 2–5 ms 且要遍历全部 entry 做 schema 投影；\n    // 为什么不会自触发死循环：dsh-settings 的 `settings/document-updated` 受\n    // `previous?.raw !== raw` 保护，而 raw 是 schema + config 的稳定序列化，\n    // 正常重复调用不 emit（04-auto-language.md 6.3 要点 5）。\n    child.effect(\n      () =>\n        child.on('settings/document-updated', (ns) => {\n          if (ns === 'locale' || ns === 'language-guard') refreshPreference(child.settings);\n        }),\n      'language-guard: ui locale cache',\n    );\n  });\n}\n\n/**\n * 配置 schema（01-mechanism.md 4.1 逐字）。\n *\n * 0.2.0 新增 `languageMode`（三态，默认空串）。默认值**故意不是 `'auto'`**：\n * 空串才能区分「用户显式选了自动」与「用户从没设置过」，这是老用户迁移\n * 规则（`lib/language.js` 的 `effectiveMode()`）能成立的前提。\n *\n * 用 `@deepseek-ai/schemastery`，**不是** zod：设置页的 volatileForm 只认\n * schemastery 的 schema 与 `meta.volatile`。`.volatile()` 必须加在**每个字段**上，\n * 不能加在根对象（会报 `volatile fields require a fixed object path without an\n * enclosing volatile field`）。\n */\nexport const Config = z === null ? undefined : z.object({\n  languageMode: z\n    .union([z.const(''), z.const('auto'), z.const('manual')])\n    .default('')\n    .description(\n      '语言模式。auto=自动跟随界面语言；manual=固定使用 targetLanguage；留空（默认）=未选择，由迁移规则推断：targetLanguage 仍是默认值 zh-CN 时按 auto，改过则按 manual（保护老用户的手动选择）。',\n    )\n    .volatile(),\n\n  targetLanguage: z\n    .string()\n    .default('zh-CN')\n    .pattern(/^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/)\n    .description(\n      '目标语言（BCP-47 语言标签）。默认 zh-CN。常见值：zh-CN 简体中文、zh-TW 繁體中文、en English、ja 日本語、ko 한국어。',\n    )\n    .volatile(),\n\n  strength: z\n    .union([z.const('B'), z.const('C'), z.const('D')])\n    .default('C')\n    .description(\n      '强度档位。B=基础（提示词首尾两段约束）；C=强化（首尾两段 + 工具说明后重申，推荐）；D=周期（强化 + 每 N 轮注入一次语言自检）。',\n    )\n    .volatile(),\n\n  injectEveryNRounds: z\n    .number()\n    .min(3)\n    .max(50)\n    .step(1)\n    .default(8)\n    .description('D 档每多少轮注入一次语言自检（3–50，默认 8）。仅 strength=D 时生效。')\n    .volatile(),\n\n  preserveCodeTerms: z\n    .boolean()\n    .default(true)\n    .description('保持代码、命令、路径、标识符与英文报错原样，不翻译。默认开启。')\n    .volatile(),\n\n  extraRules: z\n    .string()\n    .default('')\n    .description('附加约束，追加在内置规则之后（团队或项目自定义条款）。留空则只用内置规则。')\n    .volatile(),\n\n  overrideHead: z\n    .string()\n    .default('')\n    .description('高级：完全替换首段内置规则文本。留空使用内置规则；非空时 extraRules 仍会追加在其后。')\n    .volatile(),\n});\n"
    },
    {
      "path": "lib/cycle.js",
      "content": "/**\n * D 档（周期）实现：在 `agent/pre-step` waterfall 里改写当步的 messages。\n *\n * 为什么不用 `agent.inject()`：`inject = send(input, \"next-step\", false)`，消息进\n * inbox、要等下一个 step 边界才被 claim，而且不唤醒驱动器。周期提醒的最佳时机是\n * 「当轮第一个 step 已装配、模型还没开始写」——正是 `agent/pre-step` 的位置。\n * （依据与逐条理由见 docs/decisions/01-mechanism.md 6.2 节。）\n *\n * 硬约束（缺任何一条都会出问题）：\n * 1. 先 `await next()`，不拥有决策就原样返回；\n * 2. 必须 `{ ...decision, messages }` spread，保住 `startsRequestSeries` 等字段；\n * 3. 门禁 `step === 1 && decision.messages.length > 0`——缺了会让 turn 永不结束；\n * 4. 幂等：本步已有同款消息就不再追加。\n */\n\nimport { createUserMessage } from '@deepseek-ai/dsh-llm';\nimport { reminderText } from './text.js';\n\n/** 提醒消息在 source.kind 上的标记，派生历史据此区分「插件注入」与真实用户输入 */\nconst SOURCE_KIND = 'language-guard';\n\n/**\n * 子代理判定：`agent` 上没有 `parent` 字段，官方写法是取两个深度的较大值。\n * 0 表示顶层会话，非 0 表示子代理（子代理继承父会话的 system prompt 约束已足够）。\n * @param {any} agent\n * @returns {number}\n */\nfunction delegationDepthOf(agent) {\n  const fromHeader = agent?.session?.header?.delegationDepth;\n  const fromOptions = agent?.options?.subagentDepth;\n  const depth = Math.max(Number(fromHeader ?? 0) || 0, Number(fromOptions ?? 0) || 0);\n  return depth;\n}\n\n/**\n * 构造周期提醒消息。`source` 是必填项：没有标签的上下文会在派生历史里\n * 被渲染成用户提示词；`kind` 也绝不能是 `user` 或 `runtime-context`。\n * @param {string} language\n */\nfunction buildReminder(language) {\n  return createUserMessage({\n    content: [{ type: 'text', text: reminderText({ language }) }],\n    source: { kind: 'language-guard', form: 'notice', summary: '语言自检' },\n  });\n}\n\n/**\n * 注册 D 档监听。注册在插件根 ctx 上：payload 自带 agent，本监听不持有\n * 任何 per-agent 状态，随插件卸载自动清理。\n *\n * @param {any} ctx 插件根上下文\n * @param {{ strength: () => string, interval: () => number, language: () => string }} options\n * @returns {() => void} 清理函数\n */\nexport function registerCycle(ctx, { strength, interval, language }) {\n  return ctx.on('agent/pre-step', async ({ agent, messages, turn, step }, next) => {\n    const decision = await next();\n\n    // 不拥有决策就原样返回（绝不能替换成自己的 enter）\n    if (!decision || decision.kind === 'reject') return decision;\n\n    // 只有 D 档需要周期提醒；其余档位直接透传下游决策\n    if (strength() !== 'D') return decision;\n\n    // 门禁：只在命中轮的第一个 step、且有真实输入时插入\n    if (step !== 1) return decision;\n    if (!Array.isArray(decision.messages) || decision.messages.length === 0) return decision;\n\n    const every = interval();\n    if (!Number.isFinite(every) || every < 1) return decision;\n    if (turn % every !== 0) return decision;\n\n    // 幂等：本步已经带过同款消息就不再追加\n    if (decision.messages.some((message) => message?.source?.kind === SOURCE_KIND)) return decision;\n\n    // 只对顶层会话注入，不污染子代理的紧凑上下文\n    if (delegationDepthOf(agent) !== 0) return decision;\n\n    // 插在「最后一个本步 claim 到的消息」之后、runtime context 之前\n    const lastClaimed = decision.messages.findLastIndex((message) => messages.includes(message));\n    const entered = decision.messages.toSpliced(lastClaimed + 1, 0, buildReminder(language()));\n\n    return { ...decision, messages: entered };\n  });\n}\n"
    },
    {
      "path": "lib/commands.js",
      "content": "/**\n * `/language` 斜杠命令：输入框里的快捷方式。\n *\n * 它**不是**面板上的「快速语言切换」——那个由 client.js 的侧栏按钮承担\n * （docs/decisions/03-manifest.md 第 2.2 节）。命令的作用是「不打开设置页、\n * 不改配置文件，临时切换本会话的语言」，因此只写内存覆盖值，不写 Config。\n *\n * `commands` 服务用 `ctx.inject` 懒注册：缺该服务的部署（无交互 UI 的 headless\n * 场景）不该让插件永久 pending，否则 system prompt 的 section 永远不会注册。\n */\n\nimport { clearLanguageOverride, setLanguageOverride } from './state.js';\nimport { languageLabel } from './text.js';\n\n/** 与 Config.targetLanguage 的 pattern 保持同一正则（01-mechanism.md 4.1） */\nconst BCP47 = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;\n\n/** 把解析来源翻译成给人看的一句话 */\nfunction sourceHint(source) {\n  if (source === 'ui') return '跟随界面语言';\n  if (source === 'fallback') return '未识别到界面语言，用配置值兜底';\n  return '手动模式';\n}\n\n/**\n * 注册 `/language` 命令。\n *\n * 与自动模式的关系：命令写的是**内存覆盖值**，优先级高于自动解析与配置值，\n * 两种模式下都生效；`reset` 清除覆盖后回到当前模式的解析结果。命令本身\n * **不写配置**，所以不会改变 `languageMode` —— 自动模式不会因为一次临时\n * 切换就被静默改成手动（票 #14 禁止项）。\n *\n * @param {any} ctx 插件根上下文\n * @param {{\n *   language: () => string,\n *   configured: () => string,\n *   mode?: () => 'auto' | 'manual',\n *   source?: () => 'manual' | 'ui' | 'fallback',\n * }} options\n */\nexport function registerCommands(ctx, { language, configured, mode, source }) {\n  ctx.inject(['commands'], (child) => {\n    child.effect(\n      () =>\n        child.commands.register({\n          name: 'language',\n          description: '切换本会话的目标语言（只影响当前进程，不写入配置）',\n          input: { hint: '<语言标签，如 ja；reset 恢复配置值>' },\n          handler: ({ rawInput }) => {\n            const raw = typeof rawInput === 'string' ? rawInput.trim() : '';\n\n            if (!raw) {\n              const current = language();\n              const saved = configured();\n              const currentMode = typeof mode === 'function' ? mode() : 'manual';\n              const origin =\n                currentMode === 'manual'\n                  ? '手动模式'\n                  : `自动模式，${sourceHint(typeof source === 'function' ? source() : 'ui')}`;\n              const suffix =\n                currentMode === 'auto' && current !== saved ? `（配置值：${saved}）` : '';\n              return {\n                kind: 'success',\n                text: `当前目标语言：${languageLabel(current)}（${current}）· ${origin}${suffix}`,\n              };\n            }\n\n            if (raw === 'reset' || raw === 'default') {\n              clearLanguageOverride();\n              const restored = language();\n              const currentMode = typeof mode === 'function' ? mode() : 'manual';\n              const where = currentMode === 'manual' ? '配置中的目标语言' : '自动解析结果';\n              return {\n                kind: 'success',\n                text: `已恢复为${where}：${languageLabel(restored)}（${restored}）`,\n              };\n            }\n\n            if (!BCP47.test(raw)) {\n              return {\n                kind: 'error',\n                text: `不是合法的 BCP-47 语言标签：${raw}（示例：zh-CN、zh-TW、en、ja、ko）`,\n              };\n            }\n\n            setLanguageOverride(raw);\n            return {\n              kind: 'success',\n              text: `本会话目标语言已切换为 ${languageLabel(raw)}（${raw}），下一条消息起生效。`,\n            };\n          },\n        }),\n      'language-guard: /language command',\n    );\n  });\n}\n"
    },
    {
      "path": "client.js",
      "content": "/**\n * dsh-language-guard —— Client 半。\n *\n * 唯一真源：docs/decisions/02-panel.md（交互与文案）、docs/decisions/03-manifest.md\n * 第 2.2 节（装载契约）。\n *\n * 只做两件事：\n * 1. 在「设置 → 插件 → dsh-language-guard」详情页渲染配置卡片（slot `plugins.bundle.config`）；\n * 2. 在侧栏底部渲染快速语言切换按钮（slot `sidebar.footer.action`）。\n *\n * 硬规则（逐条对应 references/ui-plugin.md 与 practices.md）：\n * - `id` 必须等于包名；`factory` 无副作用，所有注册都在 `apply` 里；\n * - 不加载任何 Harness Client 包（控件全部自绘），不替换 app root，不往 body 追加应用；\n * - 不在组件外写 DOM；样式用 `<style>` React 元素渲染，监听器在 effect 里注册并清理；\n * - 只用 `--dsw-alias-*` 主题 token，不写字面颜色，明暗适配交给宿主主题（不写任何媒体查询分支）；\n * - 所有可见文案走 `ctx.locale`，不硬编码。\n */\n\nwindow.__ModuleLoader__.load({\n  id: 'dsh-language-guard',\n\n  factory(require) {\n    const React = require('react');\n    const h = React.createElement;\n\n    /** locale 命名空间：同一份字典同时服务设置卡片与侧栏控件 */\n    const NS = 'languageGuard';\n\n    /** 配置表单的 entryId：cordis 行 id === 包名 */\n    const ENTRY_ID = 'dsh-language-guard';\n\n    /** 与 Host 侧 Config.targetLanguage 的 pattern 保持同一正则 */\n    const BCP47 = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;\n\n    /** 三档强度的取值顺序 */\n    const LEVELS = ['B', 'C', 'D'];\n\n    /** 快速切换与设置页 chip 共用的预设（5 个高频语言） */\n    const PRESETS = [\n      { code: 'zh-CN', labelKey: 'language.preset.zhCN' },\n      { code: 'zh-TW', labelKey: 'language.preset.zhTW' },\n      { code: 'en', labelKey: 'language.preset.en' },\n      { code: 'ja', labelKey: 'language.preset.ja' },\n      { code: 'ko', labelKey: 'language.preset.ko' },\n    ];\n\n    /**\n     * 语言模式常量与解析规则。\n     *\n     * **本段是 `lib/language.js` 的逐条镜像**：Client 半是独立 bundle\n     * （`window.__ModuleLoader__.load` 的 factory 只能 `require('react')`，\n     * 不能相对 import 包内其他文件），因此无法直接复用 Host 侧的模块。\n     * 改这里的任何一条规则，必须同步改 `lib/language.js`，反之亦然。\n     *\n     * 谁在守这份一致性（各管一段，别混淆）：\n     *\n     * - `scripts/verify-mirror.mjs`（清单里的 **M14**）：把本段从 `client.js`\n     *   抽出来做**运行时行为比对**，与 `lib/language.js` 在\n     *   `LANGS × MODES × FALLBACKS × DEFAULTS` 上逐条比输出，覆盖本段\n     *   全部 5 个函数（`normalizeLocaleId` / `mapPreference` / `effectiveMode` /\n     *   `resolveTargetLanguage` / `resolveSource`）。**这才是防漂移的主判据。**\n     * - `scripts/verify-checklist.sh` 的 **M1 / M2**：两侧**源文本**正则比对，\n     *   但只覆盖 `mapPreference` 的两条规则（zh / en）与 `effectiveMode` 的三元式，\n     *   是文本层面的抽查，不是行为断言。\n     * - 同脚本的 **M3** 是 Config 默认值、**M4** 是 radio group 结构，\n     *   都跟本段一致性无关。\n     * - `scripts/verify-language.mjs` 只 import `lib/language.js`，断言的是\n     *   **Host 侧**行为，从不读 `client.js`。\n     */\n    const MODE_AUTO = 'auto';\n    const MODE_MANUAL = 'manual';\n    const MODE_UNSET = '';\n    const DEFAULT_LANGUAGE = 'zh-CN';\n\n    /**\n     * 精确镜像 Host 侧的默认参数语义 `defaultLanguage = 'zh-CN'`。\n     *\n     * **不能用 `||`，也不能用 `??`**：\n     *\n     * - `||` 对任何假值兜底 —— `''` / `null` 都会被换成 `'zh-CN'`；\n     * - `??` 对 `null` 与 `undefined` 兜底 —— `null` 会被换成 `'zh-CN'`；\n     * - JS 默认参数**只对 `undefined` 生效** —— `''` 与 `null` 原样传入。\n     *\n     * Host 的 `effectiveMode` / `resolveTargetLanguage` / `resolveSource` 用的正是\n     * 默认参数，所以这里必须只在 `undefined` 时兜底，否则 `defaultLanguage: null`\n     * 会让 Host 判 `manual` 而 Client 判 `auto` —— 正是 `verify-mirror.mjs`\n     * 的 `DEFAULTS` 维度要抓的那类分叉。\n     */\n    function pickDefaultLanguage(input) {\n      const given = input ? input.defaultLanguage : undefined;\n      return given === undefined ? DEFAULT_LANGUAGE : given;\n    }\n\n    /** 归一化语言标识：去空白、下划线转连字符、校验 BCP-47 */\n    function normalizeLocaleId(raw) {\n      if (typeof raw !== 'string') return null;\n      const text = raw.trim().replace(/_/g, '-');\n      if (!text) return null;\n      return BCP47.test(text) ? text : null;\n    }\n\n    /** 界面语言 → targetLanguage（四条规则，与 Host 侧 mapPreference 一致） */\n    function mapPreference(preference) {\n      const id = normalizeLocaleId(preference);\n      if (!id) return null;\n      const primary = id.split('-')[0].toLowerCase();\n      if (primary === 'zh') return 'zh-CN';\n      if (primary === 'en') return 'en';\n      return id;\n    }\n\n    /** 三态 → 两态（含「老用户手选过语言」迁移规则） */\n    function effectiveMode(input) {\n      const defaultLanguage = pickDefaultLanguage(input);\n      const rawMode = input && typeof input.languageMode === 'string'\n        ? input.languageMode.trim().toLowerCase()\n        : '';\n      if (rawMode === MODE_MANUAL) return MODE_MANUAL;\n      if (rawMode === MODE_AUTO) return MODE_AUTO;\n      const target = normalizeLocaleId(input && input.targetLanguage) || defaultLanguage;\n      return target === defaultLanguage ? MODE_AUTO : MODE_MANUAL;\n    }\n\n    /**\n     * 解析最终生效的 targetLanguage（与 Host 侧 `lib/language.js` 的\n     * `resolveTargetLanguage` 逐字等价）：\n     *\n     * ```\n     * manual 态 → fallback（默认 zh-CN）\n     * auto   态 → mapPreference(preference) ?? fallback（默认 zh-CN）\n     * ```\n     *\n     * `input.mode` 是**原始的** `languageMode`（可以是 `''`），三态判定在本函数内部做，\n     * 保证「老用户手选过语言」的迁移规则在任何调用点都生效。\n     */\n    function resolveTargetLanguage(input) {\n      const defaultLanguage = pickDefaultLanguage(input);\n      const base = normalizeLocaleId(input && input.fallback) ?? defaultLanguage;\n      const effective = effectiveMode({\n        languageMode: input && input.mode,\n        targetLanguage: input && input.fallback,\n        defaultLanguage,\n      });\n      if (effective === MODE_MANUAL) return base;\n      return mapPreference(input && input.preference) ?? base;\n    }\n\n    /** 解析来源：manual / ui / fallback */\n    function resolveSource(input) {\n      const defaultLanguage = pickDefaultLanguage(input);\n      const mode = effectiveMode({\n        languageMode: input && input.mode,\n        targetLanguage: input && input.fallback,\n        defaultLanguage,\n      });\n      if (mode === MODE_MANUAL) return 'manual';\n      return mapPreference(input && input.preference) ? 'ui' : 'fallback';\n    }\n\n    /** 语言标签 → 显示名（与 Host 侧 lib/text.js 的映射表一致） */\n    const LANGUAGE_NAMES = [\n      ['zh-cn', '简体中文'],\n      ['zh-hans', '简体中文'],\n      ['zh-sg', '简体中文'],\n      ['zh-tw', '繁體中文'],\n      ['zh-hk', '繁體中文'],\n      ['zh-mo', '繁體中文'],\n      ['zh-hant', '繁體中文'],\n      ['en', 'English'],\n      ['en-us', 'English'],\n      ['en-gb', 'English'],\n      ['ja', '日本語'],\n      ['ja-jp', '日本語'],\n      ['ko', '한국어'],\n      ['ko-kr', '한국어'],\n    ];\n\n    // —— 运行时 UI 字典（02-panel.md 4.4 全文；zh / en 的 key 集合必须完全一致）——\n\n    const zh = {\n      'card.title': '语言守卫',\n      'mode.legend': '语言来源',\n      'mode.auto': '自动（跟随界面语言）',\n      'mode.auto.desc': '按 DSH 的界面语言自动选择目标语言；切换界面语言后，下一条消息即生效。',\n      'mode.manual': '手动',\n      'mode.manual.desc': '固定使用下面填写的目标语言，不随界面语言变化。',\n      'mode.current': '当前解析为 {language}',\n      'mode.source.ui': '来自界面语言',\n      'mode.source.fallback': '未识别到界面语言，用配置值兜底',\n      'mode.migrated': '检测到你曾手动设置过目标语言，已保持手动模式。',\n      'mode.traditionalHint': 'DSH 内置语言只有「简体中文」与「English」，界面语言为简体时无法自动判断简繁；需要繁体请切到「手动」并选 zh-TW。',\n      'status.effective': '生效语言：{language}（{code}） · 来源：{source}',\n      'status.fallbackWarn': '未识别到界面语言，当前用配置值 {code} 兜底；如需固定语言，请切到「手动」。',\n      'status.switchManual': '切到手动',\n      'quick.menu.custom': '当前自定义：{label}',\n      'language.autoDisabled': '自动模式下不可编辑；切到「手动」即可自定义。',\n      'quick.menu.auto': '自动（跟随界面语言）',\n      'quick.menu.autoHint': '当前自动解析为 {label}',\n      'quick.menu.autoShort': '自动，{label}',\n\n      'strength.label': '强度档位',\n      'strength.recommended': '推荐',\n      'strength.basic.label': '基础',\n      'strength.basic.desc': '只在提示词首尾各放一段语言约束，成本最低，适合短会话。',\n      'strength.strong.label': '强化',\n      'strength.strong.desc': '在基础之上，于工具说明之后补一段重申，抵消英文工具说明带来的语言漂移，推荐默认。',\n      'strength.periodic.label': '周期',\n      'strength.periodic.desc': '在强化之上，每 N 轮在当轮开头追加一条语言自检提醒，适合长会话；提醒会作为一条会话记录出现，可在会话日志中看到。',\n      'interval.label': '注入间隔（轮）',\n      'interval.hint': '仅周期档生效，3–50 轮。',\n      'interval.disabled': '仅在选择「周期」档时可调。',\n      'language.label': '目标语言',\n      'language.hint': 'BCP-47 语言标签，例如 zh-CN、zh-TW、en、ja、ko。',\n      'language.invalid': '不是合法的 BCP-47 语言标签。',\n      'language.current': '当前：{code}',\n      'language.preset.zhCN': '简体中文',\n      'language.preset.zhTW': '繁體中文',\n      'language.preset.en': 'English',\n      'language.preset.ja': '日本語',\n      'language.preset.ko': '한국어',\n      'terms.label': '保留代码与术语原文',\n      'terms.hint': '代码、命令、路径、标识符与英文报错保持原样，不翻译。',\n      'advanced.summary': '覆盖首段规则（高级）',\n      'advanced.label': '首段规则全文',\n      'advanced.hint': '留空则使用内置规则；填入后完全替换首段内置文本，「附加约束」仍会追加在其后。',\n      'extraRules.label': '附加约束',\n      'extraRules.hint': '追加在内置规则之后，留空则只用内置规则。',\n      'action.save': '保存',\n      'action.discard': '放弃更改',\n      'action.reset': '恢复默认',\n      'state.saved': '已保存 · 无需重启，下一条消息即生效',\n      'state.saving': '保存中…',\n      'state.loading': '正在读取配置…',\n      'state.unavailable': '配置暂不可用，请确认插件已启用。',\n      'state.readOnly': '当前部署为只读，配置不可修改。',\n      'notice.contextConflict':\n        '若你同时安装了 dsh-context，建议清空它的 promptPrefix / promptSuffix —— 它注入的 section 与本插件同序，会重复消耗 token。',\n      'error.saveFailed': '保存失败：{message}',\n      'error.retry': '重试',\n      'quick.aria': '切换目标语言，当前 {label}',\n      'quick.menu.title': '目标语言',\n      'quick.menu.current': '当前：{label}',\n      'quick.menu.check': '已选中',\n      'quick.menu.hint': '其他语言可在 设置 → 插件 → 语言守卫 中填写。',\n      'quick.already': '当前已是 {label}',\n    };\n\n    const en = {\n      'card.title': 'Language Guard',\n      'mode.legend': 'Language source',\n      'mode.auto': 'Auto (follow the UI language)',\n      'mode.auto.desc': 'Picks the target language from the DSH interface language; takes effect on the next message after you switch.',\n      'mode.manual': 'Manual',\n      'mode.manual.desc': 'Always uses the target language below, regardless of the interface language.',\n      'mode.current': 'Currently resolved to {language}',\n      'mode.source.ui': 'from the interface language',\n      'mode.source.fallback': 'interface language not detected, using the configured value',\n      'mode.migrated': 'You previously set a target language manually, so manual mode is kept.',\n      'mode.traditionalHint': 'DSH ships only Simplified Chinese and English as UI languages, so Traditional Chinese cannot be detected automatically; switch to Manual and pick zh-TW.',\n      'status.effective': 'Active language: {language} ({code}) · Source: {source}',\n      'status.fallbackWarn': 'Interface language not detected; falling back to the configured value {code}. Switch to Manual to pin a language.',\n      'status.switchManual': 'Switch to Manual',\n      'quick.menu.custom': 'Custom: {label}',\n      'language.autoDisabled': 'Not editable in auto mode; switch to Manual to customize.',\n      'quick.menu.auto': 'Auto (follow the UI language)',\n      'quick.menu.autoHint': 'Currently auto-resolved to {label}',\n      'quick.menu.autoShort': 'Auto, {label}',\n\n      'strength.label': 'Strength',\n      'strength.recommended': 'Recommended',\n      'strength.basic.label': 'Basic',\n      'strength.basic.desc': 'One language constraint at the start and one at the end of the prompt. Cheapest, best for short sessions.',\n      'strength.strong.label': 'Strong',\n      'strength.strong.desc': 'Adds a restatement right after the tool descriptions on top of Basic, countering drift from English tool docs. Recommended default.',\n      'strength.periodic.label': 'Periodic',\n      'strength.periodic.desc': 'Adds a language self-check at the start of every Nth turn on top of Strong, for long sessions. The reminder appears as a session record and is visible in the session log.',\n      'interval.label': 'Injection interval (turns)',\n      'interval.hint': 'Applies to Periodic only, 3–50 turns.',\n      'interval.disabled': 'Available only when Periodic is selected.',\n      'language.label': 'Target language',\n      'language.hint': 'A BCP-47 language tag, e.g. zh-CN, zh-TW, en, ja, ko.',\n      'language.invalid': 'Not a valid BCP-47 language tag.',\n      'language.current': 'Current: {code}',\n      'language.preset.zhCN': '简体中文',\n      'language.preset.zhTW': '繁體中文',\n      'language.preset.en': 'English',\n      'language.preset.ja': '日本語',\n      'language.preset.ko': '한국어',\n      'terms.label': 'Keep code and technical terms verbatim',\n      'terms.hint': 'Code, commands, paths, identifiers, and raw English error text stay untranslated.',\n      'advanced.summary': 'Override the opening rules (advanced)',\n      'advanced.label': 'Opening rules text',\n      'advanced.hint': 'Leave empty to use the built-in rules. When set, it replaces the built-in opening text entirely; Additional rules are still appended after it.',\n      'extraRules.label': 'Additional rules',\n      'extraRules.hint': 'Appended after the built-in rules. Leave empty to use the built-in rules alone.',\n      'action.save': 'Save',\n      'action.discard': 'Discard changes',\n      'action.reset': 'Reset to default',\n      'state.saved': 'Saved · no restart needed, applies to the next message',\n      'state.saving': 'Saving…',\n      'state.loading': 'Reading configuration…',\n      'state.unavailable': 'Configuration is unavailable. Check that the plugin is enabled.',\n      'state.readOnly': 'This deployment is read-only; configuration cannot be changed.',\n      'notice.contextConflict':\n        \"If you also use dsh-context, consider clearing its promptPrefix / promptSuffix — its sections share this plugin's order and duplicate token cost.\",\n\n      'error.saveFailed': 'Save failed: {message}',\n      'error.retry': 'Retry',\n      'quick.aria': 'Switch target language, currently {label}',\n      'quick.menu.title': 'Target language',\n      'quick.menu.current': 'Current: {label}',\n      'quick.menu.check': 'Selected',\n      'quick.menu.hint': 'Other languages can be entered in Settings → Plugins → Language Guard.',\n      'quick.already': 'Already {label}',\n    };\n\n    // —— 样式：只用主题 token，类名 lg- 前缀，用 <style> React 元素渲染 ——\n\n    const CSS = `\n.lg-card { display: flex; flex